/** Every name an app's icon may be. */
export const APP_ICON_NAMES = Object.freeze(Object.keys(APP_ICONS));

/** The picker's sections, in order; the first fifteen names (today's) aren't in them, being the plainest. */
export const APP_ICON_GROUPS = Object.freeze({
  Work: Object.freeze(["work", "groups", "badge", "idCard", "supportAgent", "meetingRoom", "viewTimeline", "flag", "contract", "gavel", "policy", "school", "wavingHand", "personSearch", "handshake", "campaign", "rocketLaunch", "lightbulb", "analytics", "leaderboard", "trophy", "workspacePremium"]),
  Money: Object.freeze(["receipt", "receiptLong", "requestQuote", "payments", "savings", "accountBalanceWallet", "pointOfSale", "shoppingCartCheckout", "shoppingBag", "shoppingCart", "sell", "storefront", "cardMembership", "percent", "autorenew"]),
  Things: Object.freeze(["inventory2", "devices", "localShipping", "handyman", "construction", "homeRepairService", "directionsCar", "key", "description", "folder", "qrCode2", "bugReport", "security"]),
  Time: Object.freeze(["calendarClock", "calendarViewWeek", "eventAvailable", "confirmationNumber", "timer", "schedule", "alarm", "hourglassTop", "checklist", "taskAlt", "assignment"]),
  People: Object.freeze(["contacts", "contactMail", "familyRestroom", "childCare", "diversity3", "volunteerActivism", "forum", "chat", "reviews", "notificationImportant", "markEmailUnread", "inbox", "newspaper"]),
  Home: Object.freeze(["home", "apartment", "kitchen", "restaurant", "skillet", "localCafe", "cake", "celebration", "cleaningServices", "beachAccess", "redeem", "toys", "backpack", "pets", "pottedPlant", "eco"]),
  Health: Object.freeze(["healthAndSafety", "medicalInformation", "localHospital", "medication", "vaccines", "selfImprovement", "fitnessCenter", "directionsRun", "pedalBike", "hiking", "spa", "bedtime"]),
  Leisure: Object.freeze(["autoStories", "menuBook", "movie", "musicNote", "palette", "photoCamera", "sportsSoccer", "flight", "luggage", "map", "locationOn", "public", "editNote", "favorite", "bolt", "science", "psychology", "code"])
});

/** Whether `name` is an icon an app may wear. */
export const isAppIcon = (name) => typeof name === "string" && Object.hasOwn(APP_ICONS, name);
